namespace sv_75491f89a1a548b282bc68ab7dc1849e.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Williams"
    };

    private static readonly Dictionary<string, List<string>> DoctorTimeSlots = new()
    {
        ["Dr. Smith"] = new() { "9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM" },
        ["Dr. Johnson"] = new() { "8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM" },
        ["Dr. Patel"] = new() { "9:30 AM", "10:30 AM", "11:30 AM", "2:30 PM" },
        ["Dr. Williams"] = new() { "8:30 AM", "10:00 AM", "12:00 PM", "3:30 PM" }
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorTimeSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }
        return Task.FromResult(new List<string>());
    }

    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email, string insuranceProvider, string doctor, string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Reject "10:00 AM" as taken (simulating race condition)
        if (timeSlot == "10:00 AM")
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_75491f89a1a548b282bc68ab7dc1849e.Services
@inject AppointmentService AppointmentSvc

<h1>Book Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />

    @* STEP 1: Patient Information *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey("Email"))
            {
                <div class="validation-message">@serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-control" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
        }
    </fieldset>

    @* STEP 2: Appointment Details *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-control" @bind-Value="Model.Doctor" ValueChanged="OnDoctorChanged" ValueExpression="() => Model.Doctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey("Doctor"))
                {
                    <div class="validation-message">@serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-control" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability">Check Availability</button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || serverErrors.Count > 0)">Book Appointment</button>
        </fieldset>
    }

    @if (booked)
    {
        <div class="alert alert-success mt-3">Appointment booked successfully!</div>
    }
</EditForm>

@code {
    private AppointmentModel Model { get; set; } = new();
    private List<string> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private bool showStep2;
    private bool availabilityChecked;
    private bool booked;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        serverErrors.Clear();
        var step1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && IsValidEmail(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged(string value)
    {
        Model.Doctor = value;
        Model.TimeSlot = string.Empty;
        availabilityChecked = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(value) && Model.AppointmentDate != default)
        {
            availableSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate);
        }
        else
        {
            availableSlots = new();
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Load slots if not yet loaded
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate != default)
        {
            availableSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate);
        }

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked && serverErrors.Count == 0)
        {
            booked = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

using System.ComponentModel.DataAnnotations;

