        var step1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && IsValidEmail(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged(string value)
    {
        Model.Doctor = value;
        Model.TimeSlot = string.Empty;
        availabilityChecked = false;
        serverErrors.Clear();

        if (!string.IsNullOrEmpty(value) && Model.AppointmentDate != default)
        {
            availableSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate);
        }
        else
        {
            availableSlots = new();
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Load slots if not yet loaded
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate != default)
        {
            availableSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate);
        }

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

        if (errors.Count > 0)
        {
            serverErrors = errors;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked && serverErrors.Count == 0)
        {
            booked = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}
